//! The opencode look: `@opencode/ui`'s colour tokens as a gpui-component
//! theme (`assets/themes/opencode.json`, generated by
//! `dev/gen-opencode-theme.py`) and its fonts, Inter and IBM Plex Mono
//! (SIL OFL 1.1, `assets/fonts/`), embedded so every platform looks the same.

use std::borrow::Cow;

use gpui_kit::component::{Theme, ThemeMode, ThemeRegistry};
use gpui_kit::*;

const THEMES: &str = include_str!("../../assets/themes/opencode.json");

const FONTS: &[&[u8]] = &[
    include_bytes!("../../assets/fonts/InterVariable.ttf"),
    include_bytes!("../../assets/fonts/IBMPlexMono-Regular.ttf"),
    include_bytes!("../../assets/fonts/IBMPlexMono-Medium.ttf"),
];

/// Register the fonts and themes; call once before the first window.
pub fn install(cx: &mut App) {
    if let Err(e) = cx
        .text_system()
        .add_fonts(FONTS.iter().map(|f| Cow::Borrowed(*f)).collect())
    {
        tracing::warn!("could not load bundled fonts: {e:#}");
    }
    let registry = ThemeRegistry::global_mut(cx);
    if let Err(e) = registry.load_themes_from_str(THEMES) {
        tracing::warn!("could not load the opencode theme: {e:#}");
        return;
    }
    let themes = registry.themes().clone();
    let (Some(dark), Some(light)) = (themes.get("opencode Dark"), themes.get("opencode Light"))
    else {
        return;
    };
    let (dark, light) = (dark.clone(), light.clone());
    if !cx.has_global::<Theme>() {
        Theme::change(ThemeMode::Dark, None, cx);
    }
    let theme = Theme::global_mut(cx);
    theme.dark_theme = dark;
    theme.light_theme = light;
}

/// Apply a theme preference: "light", "system" or anything else for dark.
pub fn apply(pref: Option<&str>, window: &mut Window, cx: &mut App) {
    match pref {
        Some("light") => Theme::change(ThemeMode::Light, Some(window), cx),
        Some("system") => Theme::sync_system_appearance(Some(window), cx),
        _ => Theme::change(ThemeMode::Dark, Some(window), cx),
    }
}

#[cfg(test)]
mod tests {
    #[::core::prelude::v1::test]
    fn bundled_theme_has_both_appearances() {
        let v: serde_json::Value = serde_json::from_str(super::THEMES).unwrap();
        let names: Vec<&str> = v["themes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t["name"].as_str().unwrap())
            .collect();
        assert_eq!(names, ["opencode Dark", "opencode Light"]);
    }
}
